function throttle<T extends unknown[]>(fn: (...args: T) => void, wait: number) {
  let last = -Infinity;
  const run = (...args: T) => {
    const now = performance.now();
    if (now - last >= wait) {
      last = now;
      fn(...args);
    }
  };
  run.cancel = () => {
    last = -Infinity;
  };
  return run;
}

